class Solution {
public:
    bool uniformArray(vector<int>& nums1) {
        long long mn[2] = {LLONG_MAX, LLONG_MAX};
        for (int x : nums1) mn[x & 1] = min(mn[x & 1], (long long)x);
        for (int target = 0; target < 2; ++target) {
            bool ok = true;
            for (int x : nums1) {
                if ((x & 1) == target) continue;
                if (mn[1] >= x) { ok = false; break; }
            }
            if (ok) return true;
        }
        return false;
    }
};
